public long minimumLossBrute(long[] price) {
    int n = price.length;
    long best = Long.MAX_VALUE;
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            if (price[i] > price[j]) {
                best = Math.min(best, price[i] - price[j]);
            }
        }
    }
    return best;
}

