public long minimumLoss(long[] price) {
    int n = price.length;
    long[][] pe = new long[n][2];   // [price, originalYearIndex]
    for (int i = 0; i < n; i++) {
        pe[i][0] = price[i];
        pe[i][1] = i;
    }
    java.util.Arrays.sort(pe, (x, y) -> Long.compare(x[0], y[0]));
    long best = Long.MAX_VALUE;
    for (int k = 1; k < n; k++) {
        long higher = pe[k][0],     hiYear = pe[k][1];
        long lower  = pe[k - 1][0], loYear = pe[k - 1][1];
        if (hiYear < loYear) {       // buy higher earlier, sell lower later
            best = Math.min(best, higher - lower);
        }
    }
    return best;
}

